CREATE PROCEDURE rellenar_margen(p_lote integer)
LANGUAGE plpgsql AS $$
DECLARE
  desde integer := 0;
  maximo integer;
  n integer;
BEGIN
  SELECT max(id) INTO maximo FROM productos;
  WHILE desde < maximo LOOP
    UPDATE productos
    SET margen = precio - costo
    WHERE id > desde AND id <= desde + p_lote AND margen IS NULL;
    GET DIAGNOSTICS n = ROW_COUNT;
    COMMIT;                                   -- cada lote queda confirmado
    RAISE NOTICE 'ids % a %: % filas', desde + 1, desde + p_lote, n;
    desde := desde + p_lote;
  END LOOP;
END $$;
CALL rellenar_margen(20);
SELECT count(*) FILTER (WHERE margen IS NULL) AS sin_margen,
       min(margen) AS menor_margen, max(margen) AS mayor_margen
FROM productos;

