CREATE FUNCTION sincronizar_celular() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.celular  := coalesce(NEW.celular, NEW.telefono);
    NEW.telefono := coalesce(NEW.telefono, NEW.celular);
  ELSIF NEW.celular IS DISTINCT FROM OLD.celular THEN      -- escribió la versión nueva
    NEW.telefono := NEW.celular;
  ELSIF NEW.telefono IS DISTINCT FROM OLD.telefono THEN    -- escribió la versión vieja
    NEW.celular := NEW.telefono;
  END IF;
  RETURN NEW;
END $$;
