import random, time
import psycopg

REINTENTABLES = {"40001", "40P01"}      # serialization_failure, deadlock_detected

def en_transaccion(pool, trabajo, max_intentos=5):
    # Ejecuta trabajo(conn) en una transacción y la reintenta ENTERA ante 40001/40P01
    for intento in range(1, max_intentos + 1):
        try:
            with pool.connection() as conn:
                with conn.transaction():          # BEGIN … COMMIT (ROLLBACK si hay excepción)
                    return trabajo(conn)
        except psycopg.Error as e:
            if e.sqlstate not in REINTENTABLES or intento == max_intentos:
                raise
            # Espera exponencial con jitter: 0–50 ms, 0–100 ms, 0–200 ms… con tope de 2 s
            time.sleep(random.uniform(0, min(2.0, 0.05 * 2 ** (intento - 1))))

