const REINTENTABLES = new Set(['40001', '40P01']);
const esperar = (ms) => new Promise((resolver) => setTimeout(resolver, ms));

async function enTransaccion(pool, trabajo, maxIntentos = 5) {
  for (let intento = 1; ; intento++) {
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const resultado = await trabajo(client);
      await client.query('COMMIT');
      return resultado;
    } catch (err) {
      await client.query('ROLLBACK').catch(() => {});      // si la conexión murió, esto también falla
      if (!REINTENTABLES.has(err.code) || intento >= maxIntentos) throw err;
      await esperar(Math.random() * Math.min(2000, 50 * 2 ** (intento - 1)));
    } finally {
      client.release();
    }
  }
}

