CREATE FUNCTION registrar_pago(p_clave uuid, p_pedido integer, p_monto integer)
RETURNS TABLE (pago_id integer, nuevo boolean)
LANGUAGE plpgsql AS $$
DECLARE
  v pagos%ROWTYPE;
BEGIN
  INSERT INTO pagos (clave_idempotencia, pedido_id, monto)
  VALUES (p_clave, p_pedido, p_monto)
  ON CONFLICT (clave_idempotencia) DO NOTHING
  RETURNING pagos.id INTO pago_id;
  IF FOUND THEN
    nuevo := true;
    RETURN NEXT;
    RETURN;
  END IF;
  -- Ya existía: otra sentencia, con un snapshot nuevo, la encuentra aunque la haya confirmado otra transacción
  SELECT * INTO v FROM pagos WHERE clave_idempotencia = p_clave;
  IF v.pedido_id <> p_pedido OR v.monto <> p_monto THEN
    RAISE EXCEPTION 'La clave % ya se usó con otro pedido o monto', p_clave;
  END IF;
  pago_id := v.id;
  nuevo := false;
  RETURN NEXT;
END $$;

