CREATE FUNCTION crear_pedido(p_cliente integer, p_sku text, p_cantidad integer)
RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  v_producto integer;
  v_precio integer;
  v_pedido integer;
BEGIN
  -- Descuento atómico: si no alcanza, CHECK (stock >= 0) aborta todo con 23514
  UPDATE productos SET stock = stock - p_cantidad
  WHERE sku = p_sku
  RETURNING id, precio INTO v_producto, v_precio;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'No existe el producto %', p_sku;
  END IF;
  INSERT INTO pedidos (cliente_id, fecha, estado)
  VALUES (p_cliente, now(), 'pendiente')
  RETURNING id INTO v_pedido;
  INSERT INTO pedido_items (pedido_id, producto_id, cantidad, precio_unitario)
  VALUES (v_pedido, v_producto, p_cantidad, v_precio);
  INSERT INTO outbox (agregado, agregado_id, tipo, payload)
  VALUES ('pedido', v_pedido, 'pedido_creado',
          jsonb_build_object('pedido_id', v_pedido, 'cliente_id', p_cliente,
                             'sku', p_sku, 'cantidad', p_cantidad,
                             'total', p_cantidad * v_precio));
  RETURN v_pedido;
END $$;

