CREATE PROCEDURE rellenar_total(p_lote integer)
LANGUAGE plpgsql AS $$
DECLARE
  desde integer := 0;
  maximo integer;
BEGIN
  SELECT max(id) INTO maximo FROM pedidos;
  WHILE desde < maximo LOOP
    UPDATE pedidos p
    SET total = p.costo_despacho
              + (SELECT coalesce(sum(i.cantidad * i.precio_unitario), 0)
                 FROM pedido_items i WHERE i.pedido_id = p.id)
    WHERE p.id > desde AND p.id <= desde + p_lote AND p.total IS NULL;
    COMMIT;
    desde := desde + p_lote;
  END LOOP;
END $$;
CALL rellenar_total(50);

