CREATE FUNCTION checkout(p_clave uuid, p_cliente integer, p_items jsonb)
RETURNS TABLE (pedido_id integer, nuevo boolean, total integer)
LANGUAGE plpgsql AS $$
DECLARE
  v_subtotal integer;
  v_despacho integer;
  v_items integer;
BEGIN
  -- Precios vigentes y validación de los SKU
  SELECT sum(pr.precio * x.cantidad), count(pr.id)
  INTO v_subtotal, v_items
  FROM jsonb_to_recordset(p_items) AS x(sku text, cantidad integer)
  LEFT JOIN productos pr ON pr.sku = x.sku;
  IF v_items IS DISTINCT FROM jsonb_array_length(p_items) THEN
    RAISE EXCEPTION 'Hay productos que no existen en el pedido';
  END IF;
  v_despacho := CASE WHEN v_subtotal < 50000 THEN 3990 ELSE 0 END;

  -- La clave única decide quién crea el pedido (las llamadas simultáneas esperan aquí)
  INSERT INTO pedidos (cliente_id, fecha, estado, metodo_pago, costo_despacho, clave_idempotencia)
  VALUES (p_cliente, now(), 'pagado', 'debito', v_despacho, p_clave)
  ON CONFLICT (clave_idempotencia) DO NOTHING
  RETURNING id INTO pedido_id;

  IF NOT FOUND THEN
    -- Reintento: devolver el pedido existente (otra sentencia, snapshot nuevo)
    SELECT p.id, p.costo_despacho + sum(i.cantidad * i.precio_unitario)
    INTO pedido_id, total
    FROM pedidos p JOIN pedido_items i ON i.pedido_id = p.id
    WHERE p.clave_idempotencia = p_clave
    GROUP BY p.id;
    nuevo := false;
    RETURN NEXT;
    RETURN;
  END IF;

  INSERT INTO pedido_items (pedido_id, producto_id, cantidad, precio_unitario)
  SELECT checkout.pedido_id, pr.id, x.cantidad, pr.precio
  FROM jsonb_to_recordset(p_items) AS x(sku text, cantidad integer)
  JOIN productos pr ON pr.sku = x.sku;

  -- Descuento atómico: CHECK (stock >= 0) aborta todo si no alcanza
  UPDATE productos pr
  SET stock = pr.stock - x.cantidad
  FROM jsonb_to_recordset(p_items) AS x(sku text, cantidad integer)
  WHERE pr.sku = x.sku;

  total := v_subtotal + v_despacho;
  INSERT INTO outbox (agregado, agregado_id, tipo, payload)
  VALUES ('pedido', checkout.pedido_id, 'pedido_creado',
          jsonb_build_object('pedido_id', checkout.pedido_id, 'cliente_id', p_cliente,
                             'total', total, 'items', p_items));
  nuevo := true;
  RETURN NEXT;
END $$;

