CREATE FUNCTION sincronizar_celular() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.celular  := coalesce(NEW.celular, NEW.telefono);
    NEW.telefono := coalesce(NEW.telefono, NEW.celular);
  ELSIF NEW.celular IS DISTINCT FROM OLD.celular THEN
    NEW.telefono := NEW.celular;
  ELSIF NEW.telefono IS DISTINCT FROM OLD.telefono THEN
    NEW.celular := NEW.telefono;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER clientes_sincronizar_celular
  BEFORE INSERT OR UPDATE ON clientes
  FOR EACH ROW EXECUTE FUNCTION sincronizar_celular();

